import { MARKETS, type Market } from '../data'
import type { Ticker } from './binance'

export const SPOT_SYMBOLS = MARKETS.map(m => `${m.sym}USDT`)

/** Overlay live Binance tickers/trends on the static market metadata (falls back to demo values). */
export function liveMarkets(tickers: Record<string, Ticker>, trends: Record<string, number[]>): Market[] {
  return MARKETS.map(m => {
    const tk = tickers[`${m.sym}USDT`]
    const tr = trends[`${m.sym}USDT`]
    return tk
      ? { ...m, price: tk.price, chg: tk.chg, vol: tk.quoteVol, trend: tr && tr.length > 1 ? [...tr.slice(0, -1), tk.price] : m.trend }
      : { ...m, trend: tr ?? m.trend }
  })
}
